const select = document.querySelector('#language-select');
const menuButton = document.querySelector('.menu-toggle');
const nav = document.querySelector('.main-nav');

function setLanguage(lang) {
  const dictionary = translations[lang] || translations.pt;
  document.documentElement.lang = lang === 'pt' ? 'pt-BR' : lang;
  document.title = dictionary.metaTitle;
  document.querySelector('meta[name="description"]').setAttribute('content', dictionary.metaDescription);
  document.querySelectorAll('[data-i18n]').forEach((node) => {
    if (dictionary[node.dataset.i18n]) node.textContent = dictionary[node.dataset.i18n];
  });
  document.querySelectorAll('[data-i18n-html]').forEach((node) => {
    if (dictionary[node.dataset.i18nHtml]) node.innerHTML = dictionary[node.dataset.i18nHtml];
  });
  document.querySelectorAll('[data-whatsapp]').forEach((link) => {
    link.href = `https://wa.me/353833831201?text=${encodeURIComponent(dictionary.whatsapp)}`;
  });
  document.querySelectorAll('[data-site-whatsapp]').forEach((link) => {
    link.href = `https://wa.me/353833831201?text=${encodeURIComponent(dictionary.site_whatsapp)}`;
  });
  document.querySelectorAll('[data-service-whatsapp]').forEach((link) => {
    const service = dictionary[link.dataset.serviceWhatsapp];
    const message = dictionary.service_whatsapp.replace('{service}', service);
    link.href = `https://wa.me/353833831201?text=${encodeURIComponent(message)}`;
  });
  document.querySelectorAll('[data-question-whatsapp]').forEach((link) => {
    link.href = `https://wa.me/353833831201?text=${encodeURIComponent(dictionary.question_whatsapp)}`;
  });
  select.value = lang;
  localStorage.setItem('me-language', lang);
}

select.addEventListener('change', (event) => setLanguage(event.target.value));
menuButton.addEventListener('click', () => {
  const isOpen = nav.classList.toggle('open');
  menuButton.setAttribute('aria-expanded', String(isOpen));
});
nav.querySelectorAll('a').forEach((link) => link.addEventListener('click', () => {
  nav.classList.remove('open');
  menuButton.setAttribute('aria-expanded', 'false');
}));

const observer = new IntersectionObserver((entries) => {
  entries.forEach((entry) => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
      observer.unobserve(entry.target);
    }
  });
}, { threshold: .12 });

document.querySelectorAll('.reveal').forEach((node) => observer.observe(node));
setLanguage(localStorage.getItem('me-language') || 'pt');
